class Solution:
    def topKFrequent(self, nums, k):
        import heapq
        counts = {}
        for value in nums:
            counts[value] = counts.get(value, 0) + 1
        heap = []
        for value, frequency in counts.items():
            heapq.heappush(heap, (frequency, value))
            if len(heap) > k:
                heapq.heappop(heap)
        return [value for _, value in heap]
